'use strict'
// اختبارات المسير اللي بتكتب أيام حضور بعينها محتاجة شهر مسير «في المستقبل»: تجسيد الغياب وإعادة حساب اليوم مابيتجاوزوش النهارده،
// وأي يوم شغل فات من غير صف حضور بيتحسب غياب. التواريخ كانت مكتوبة على أكتوبر ونوفمبر 2026، فالاختبارات بقت تفشل من أول ما أكتوبر بدأ.
// الحل من غير تغيير ولا رقم في الاختبار: نفس الشهور بنفس أيام أسبوعها في أول سنة جاية أكتوبرها بيبدأ يوم خميس زي 2026 (2037، وبعدها 2043).
// صالح للشهور من مارس لديسمبر بس (السنة الكبيسة بتفرّق يناير وفبراير).
function futureYearLike2026(today = new Date()) {
  let year = today.getFullYear() + 1
  while (new Date(year, 9, 1).getDay() !== 4) year += 1
  return year
}
const YEAR = futureYearLike2026()

/** تاريخ أو شهر مكتوب على 2026 (مارس لديسمبر) ← نفسه في السنة المستقبلية بنفس يوم الأسبوع */
function future(value) {
  const text = String(value)
  if (!/^2026-(0[3-9]|1[0-2])(-\d{2})?$/.test(text)) throw new Error(`future(): تاريخ أو شهر 2026 من مارس لديسمبر، مش «${text}»`)
  return `${YEAR}${text.slice(4)}`
}

module.exports = { YEAR, future, futureYearLike2026 }
